# verification-helper: PROBLEM https://onlinejudge.u-aizu.ac.jp/problems/ITP1_1_A
import cplib/modint/modint64
import strutils

proc check[T](parts: seq[string]) =
    let a = T.init(parseBiggestUInt(parts[1]).uint64)
    let b = T.init(parseBiggestUInt(parts[2]).uint64)
    let exponent = parseBiggestUInt(parts[3]).uint64
    let signed = parseBiggestInt(parts[4]).int64
    let parsed = T.parseModint64(parts[5])
    template equalsExpected(value: untyped, field: int) =
        doAssert value.val == parseBiggestUInt(parts[6 + field]).uint64
    equalsExpected(a, 0)
    equalsExpected(b, 1)
    equalsExpected(a + b, 2)
    equalsExpected(a - b, 3)
    equalsExpected(a * b, 4)
    equalsExpected(a.pow(exponent), 5)
    if a.val == 0:
        doAssert parts[12] == "zero"
    else:
        equalsExpected(a.inv, 6)
    if b.val == 0:
        doAssert parts[13] == "zero"
    else:
        equalsExpected(a / b, 7)
    equalsExpected(T.init(signed), 8)
    equalsExpected(parsed, 9)
    equalsExpected(-a, 10)
    var sum = a
    var difference = a
    var product = a
    sum += b
    difference -= b
    product *= b
    equalsExpected(sum, 11)
    equalsExpected(difference, 12)
    equalsExpected(product, 13)
    equalsExpected(a + signed, 14)
    equalsExpected(signed - a, 15)
    equalsExpected(signed * a, 16)
    doAssert $a == parts[6]
    doAssert $b == parts[7]
    doAssert $parsed == parts[15]

